import sys
import requests
from datetime import datetime
from threading import Lock
from time import sleep

LOG_FILE = "results.log"
MAX_CONCURRENT_REQUESTS = 3
REQUEST_TIMEOUT = 5
MAX_ATTEMPTS = 3
RETRY_DELAY = 1

def sanitize_error(error):
    return " ".join(error.split())

def log_result(url, status, bytes_received, error):
    timestamp = datetime.utcnow().isoformat() + "Z"
    with open(LOG_FILE, "a") as f:
        f.write(f"{timestamp}\t{url}\t{status}\t{bytes_received}\t{error}\n")

def check_url(url):
    last_error = None
    for attempt in range(MAX_ATTEMPTS):
        try:
            response = requests.get(url, timeout=REQUEST_TIMEOUT)
            status = response.status_code
            bytes_received = len(response.content)
            log_result(url, status, bytes_received, "")
            return
        except requests.RequestException as e:
            last_error = sanitize_error(str(e))
            if attempt < MAX_ATTEMPTS - 1:
                sleep(RETRY_DELAY)
    log_result(url, 0, 0, last_error)

def main():
    lock = Lock()
    current_requests = 0

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        with lock:
            if current_requests >= MAX_CONCURRENT_REQUESTS:
                sleep(1)
                continue
            current_requests += 1

        try:
            check_url(line)
        except Exception:
            pass

        with lock:
            current_requests -= 1

if __name__ == "__main__":
    main()

import sys
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timedelta

def process_url(url):
    try:
        response = requests.get(url, timeout=5)
        return url, response.status_code, ""
    except requests.exceptions.RequestException as e:
        return url, 0, str(e).replace('\t', ' ').replace('\n', ' ')

def main():
    urls = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            urls.append(line)

    with open('results.log', 'a') as log_file:
        with ThreadPoolExecutor(max_workers=1) as executor:
            futures = []
            for url in urls:
                future = executor.submit(process_url, url)
                futures.append(future)

            for future in as_completed(futures):
                url, status, error = future.result()
                log_file.write(f"{url}\t{status}\t{error}\n")

if __name__ == "__main__":
    main()

import sys
import time
import requests
from requests.exceptions import RequestException

def process_url(url):
    start_time = time.time()
    try:
        response = requests.get(url, timeout=5)
        elapsed = time.time() - start_time
        if elapsed < 1:
            time.sleep(1 - elapsed)
        return response.status_code, "", None
    except RequestException:
        return 0, "request failed", None

def main():
    urls = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            urls.append(line)

    with open('results.log', 'a') as log_file:
        for i, url in enumerate(urls):
            status, error, _ = process_url(url)
            log_file.write(f"{url}\t{status}\t{error}\n")
            if i < len(urls) - 1:
                time.sleep(1)

if __name__ == "__main__":
    main()

