import time
from datetime import datetime

def main():
    with open('results.log', 'a') as log_file:
        last_time = None
        while True:
            try:
                url = input().strip()
                if not url:
                    continue
                if last_time and (datetime.now() - last_time).total_seconds() < 1:
                    time.sleep(1 - (datetime.now() - last_time).total_seconds())
                last_time = datetime.now()
                try:
                    response = requests.get(url, timeout=5, allow_redirects=False)
                    status = int(response.status_code)
                    log_file.write(f"{url}\t{status}\t\n")
                except requests.RequestException:
                    status = 0
                    log_file.write(f"{url}\t0\trequest failed\n")
            except EOFError:
                break

if __name__ == "__main__":
    main()

